package dev.trentdb.execution.physical; import dev.trentdb.common.vector.DataChunk; import dev.trentdb.execution.ddl.TransactionalDdlExecutor; import dev.trentdb.planner.logical.LogicalDelete; import java.util.List; public final class PhysicalDelete implements PhysicalSource { private final TransactionalDdlExecutor executor; private final LogicalDelete logical; public PhysicalDelete(TransactionalDdlExecutor executor,LogicalDelete logical){this.executor=executor;this.logical=logical;} @Override public PhysicalOperatorType type(){return PhysicalOperatorType.DELETE;} @Override public void execute(PhysicalChunkConsumer consumer){executor.delete(logical.statement());consumer.accept(DataChunk.empty(List.of()));} }
